#!/usr/bin/env python3
"""Generate the forward migration exclusively from canonical scanner SQL."""
from pathlib import Path
root = Path(__file__).resolve().parents[1]
files = [f'database/functions/scanning/{n}.sql' for n in ['schema','settings','projection','sessions','admission','snapshots','support','grants']]
files += [f'database/functions/eshop_orders/{n}.sql' for n in ['update_ticket_to_used','update_ticket_to_used_ws','update_order_and_tickets_to_paid','get_occasion_by_scan_code','scan_ticket','update_scan_code','check_order_is_mutable','update_ticket_to_unused_ws']]
files += ['database/functions/others/duplicate_occasion.sql','database/functions/events/get_event_participants_for_edit.sql']
(root/'supabase/migrations/20261019030000_web_scanner.sql').write_text('-- Generated by automation/assemble-scanner-migration.py. Do not edit.\n'+'\n'.join('-- Source: '+f+'\n'+(root/f).read_text() for f in files))
